import { useEffect, useMemo, useRef, useState } from 'react'
import {
  Activity, ArrowLeft, Bell, Building2, Calculator, CalendarClock, Camera, Car, Check, CheckCircle2,
  ChevronDown, ChevronLeft, ChevronRight, CircleDollarSign, ClipboardList,
  Clock3, Download, FileCheck2, FileText, Gauge, History, LayoutDashboard,
  KeyRound, LoaderCircle, LogOut, Mail, MapPin, Menu, MessageCircle, MoreHorizontal, Paintbrush,
  Phone, Plus, ReceiptText, RefreshCcw, Search, Send, Settings, ShieldCheck,
  Sparkles, TrendingUp, Upload, User, UserPlus, Users, WalletCards, Wrench, X,
  Zap, type LucideIcon,
} from 'lucide-react'
import { api, login as apiLogin, register as apiRegister, requestPasswordReset, session, subscribe, updatePassword } from './api'
import { BRAND } from './brand'

type Page = 'dashboard'|'orders'|'customers'|'quotes'|'sales'|'accounting'|'reports'|'billing'|'settings'
type Stage = 'Ingreso'|'Diagnóstico'|'Cotización'|'Autorización'|'Reparación'|'Control de calidad'|'Entrega'
type Vehicle = {id:string;plate:string;brand:string;model:string;year:number;color:string;mileage:number}
type Customer = {id:string;type:string;documentType:string;document:string;name:string;phone:string;email:string;address:string;vehicles:Vehicle[]}
type Evidence = {id:string;url:string;name:string;type:string;caption:string;at:string;author:string}
type Note = {id:string;author:string;role:string;at:string;text:string}
type QuoteItem = {id:string;name:string;type:string;qty:number;price:number}
type Order = {
  id:string;customerId:string;vehicleId?:string;customer:string;phone:string;car:string;plate:string;
  serviceArea:string;affectedAreas:string[];paintColor:string;tech:string;stage:Stage;progress:number;
  value:number;delivery:string;color:string;mileage:number;fuel:string;receivedItems:string;reason:string;
  diagnosis:string;finalDiagnosis:string;arrivalContact:string;deliveryContact:string;createdAt:string;
  notes:Note[];evidence:Evidence[];quote:{status:string;taxRate:number;items:QuoteItem[]};
  history:{id:string;event:string;at:string;author:string}[]
}
type Expense={id:string;date:string;category:string;description:string;amount:number}
type Invoice={id:string;orderId:string;customer:string;date:string;total:number;status:string;nextMaintenance:string}
type Workshop={id?:string;name:string;businessType:string;nit:string;address:string;city:string;phone:string;whatsapp:string;email:string}
type Plan={id:string;name:string;description:string;monthlyPrice:number;annualPrice:number;recommended:boolean;limits:{users:number;monthlyOrders:number;storageGb:number;locations:number;evidencePerOrder:number};features:string[]}
type Subscription={planId:string;status:string;billingPeriod:'monthly'|'annual';trialEndsAt?:string;currentPeriodEndsAt?:string|null}
type CurrentUser={id:string;name:string;email:string;role:string}
type Bootstrap={currentUser?:CurrentUser;workshop:Workshop;customers:Customer[];orders:Order[];expenses:Expense[];invoices:Invoice[];activity:any[];subscription?:Subscription}

const stages:Stage[]=['Ingreso','Diagnóstico','Cotización','Autorización','Reparación','Control de calidad','Entrega']
const serviceAreas=['Mecánica general','Diagnóstico especializado','Electricidad automotriz','Latonería y pintura','Aire acondicionado','Llantas y alineación','Detailing y estética','Servicio comercial automotor']
const money=(v:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v||0)
const dateText=(v:string)=>{try{return new Intl.DateTimeFormat('es-CO',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return v}}
const initials=(name:string)=>name.split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()

function Logo(){return <div className="logo"><div className="logo-mark"><Wrench size={21}/></div><div><strong>{BRAND.firstWord}<span>{BRAND.accentWord}</span></strong><small>{BRAND.tagline}</small></div></div>}

type AuthMode='login'|'register'|'forgot'|'reset'
type RegisterForm={workshopName:string;nit:string;city:string;phone:string;fullName:string;email:string;password:string;confirmPassword:string;terms:boolean}

function Login({onLogin,onAuthenticated}:{onLogin:(email:string,password:string)=>Promise<void>;onAuthenticated:()=>void}){
  const localDemo=import.meta.env.DEV
  const hashParams=new URLSearchParams(window.location.hash.replace(/^#/,''))
  const recoveryToken=hashParams.get('access_token')||''
  const queryMessage=new URLSearchParams(window.location.search).get('auth')==='confirmed'?'Correo confirmado. Ya puedes iniciar sesión.':''
  const[mode,setMode]=useState<AuthMode>(recoveryToken?'reset':'login')
  const[email,setEmail]=useState(localDemo?'motorpro@gmail.com':'')
  const[password,setPassword]=useState(localDemo?BRAND.demoPassword:'')
  const[confirmPassword,setConfirmPassword]=useState('')
  const[show,setShow]=useState(false)
  const[loading,setLoading]=useState(false)
  const[error,setError]=useState('')
  const[success,setSuccess]=useState(queryMessage)
  const[registerForm,setRegisterForm]=useState<RegisterForm>({workshopName:'',nit:'',city:'',phone:'',fullName:'',email:'',password:'',confirmPassword:'',terms:false})
  const changeMode=(next:AuthMode)=>{setMode(next);setError('');setSuccess('');setPassword('');setConfirmPassword('')}
  const updateRegister=(key:keyof RegisterForm,value:string|boolean)=>setRegisterForm(current=>({...current,[key]:value}))

  const submitLogin=async(e:React.FormEvent)=>{e.preventDefault();setLoading(true);setError('');try{await onLogin(email,password)}catch(err){setError(err instanceof Error?err.message:'No fue posible ingresar')}finally{setLoading(false)}}
  const submitRegister=async(e:React.FormEvent)=>{
    e.preventDefault();setError('');setSuccess('')
    if(registerForm.password!==registerForm.confirmPassword)return setError('Las contraseñas no coinciden')
    if(!registerForm.terms)return setError('Debes aceptar los términos y el tratamiento de datos')
    setLoading(true)
    try{
      const result=await apiRegister(registerForm)
      if(result.token){onAuthenticated();return}
      setMode('login');setEmail(registerForm.email);setSuccess(result.message)
    }catch(err){setError(err instanceof Error?err.message:'No fue posible crear la cuenta')}
    finally{setLoading(false)}
  }
  const submitForgot=async(e:React.FormEvent)=>{e.preventDefault();setLoading(true);setError('');setSuccess('');try{const result=await requestPasswordReset(email);setSuccess(result.message)}catch(err){setError(err instanceof Error?err.message:'No fue posible enviar el enlace')}finally{setLoading(false)}}
  const submitReset=async(e:React.FormEvent)=>{
    e.preventDefault();setError('');setSuccess('')
    if(password!==confirmPassword)return setError('Las contraseñas no coinciden')
    setLoading(true)
    try{const result=await updatePassword(recoveryToken,password);window.history.replaceState({},'',window.location.pathname);setMode('login');setPassword('');setConfirmPassword('');setSuccess(result.message)}catch(err){setError(err instanceof Error?err.message:'No fue posible actualizar la contraseña')}finally{setLoading(false)}
  }

  return <main className="login-shell">
    <section className="login-visual"><div className="visual-glow one"/><div className="visual-glow two"/><Logo/><div className="login-copy"><span className="eyebrow light"><Sparkles size={15}/> Plataforma automotriz multiservicio</span><h1>Más control.<br/><em>Mejor servicio.</em></h1><p>Mecánica, diagnóstico, electricidad, pintura, latonería y servicios automotrices en una sola operación.</p><div className="login-benefits"><div><CheckCircle2/><span><b>Trazabilidad total</b><small>Del ingreso a la entrega</small></span></div><div><MessageCircle/><span><b>Cliente siempre informado</b><small>Mensajes y evidencias por WhatsApp</small></span></div><div><ShieldCheck/><span><b>Datos persistentes</b><small>Base de datos segura por taller</small></span></div></div></div><div className="visual-footer">{BRAND.name} © 2026 · Hecho para talleres que avanzan</div></section>
    <section className={`login-panel ${mode==='register'?'register-panel':''}`}><div className="mobile-login-logo"><Logo/></div>
      {mode==='login'&&<form className="login-card" onSubmit={submitLogin}><span className="welcome-icon"><User size={24}/></span><h2>Bienvenido de nuevo</h2><p>Ingresa para administrar tu taller</p>{success&&<div className="auth-message success"><CheckCircle2/>{success}</div>}<label>Correo electrónico<div className="input-wrap"><Mail size={18}/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></div></label><label>Contraseña<div className="input-wrap"><KeyRound size={18}/><input type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/><button type="button" className="text-button" onClick={()=>setShow(!show)}>{show?'Ocultar':'Ver'}</button></div></label><div className="login-options"><span>Acceso seguro</span><button type="button" className="auth-link" onClick={()=>changeMode('forgot')}>¿Olvidaste tu contraseña?</button></div>{error&&<p className="form-error">{error}</p>}<button className="primary-button login-button" disabled={loading}>{loading?<LoaderCircle className="spin"/>:<>Ingresar al taller <ChevronRight size={18}/></>}</button><div className="auth-divider"><span>¿Tu taller aún no usa TallerPilot?</span></div><button type="button" className="secondary-button auth-secondary" onClick={()=>changeMode('register')}><Building2/>Crear una cuenta nueva</button>{localDemo&&<div className="demo-note"><Zap size={16}/><span><b>Acceso local de demostración</b><small>motorpro@gmail.com · {BRAND.demoPassword}</small></span></div>}</form>}
      {mode==='register'&&<form className="login-card register-card" onSubmit={submitRegister}><button type="button" className="auth-back" onClick={()=>changeMode('login')}><ArrowLeft/>Volver al inicio</button><span className="welcome-icon"><Building2 size={24}/></span><h2>Crea la cuenta de tu taller</h2><p>Empieza gratis, sin tarjeta y sin límite de tiempo.</p><div className="register-grid"><label>Nombre del taller<div className="input-wrap"><Building2/><input value={registerForm.workshopName} onChange={e=>updateRegister('workshopName',e.target.value)} placeholder="Ej. Taller El Progreso" required/></div></label><label>NIT o documento<div className="input-wrap"><FileText/><input value={registerForm.nit} onChange={e=>updateRegister('nit',e.target.value)} placeholder="Sin puntos ni espacios" required/></div></label><label>Ciudad<div className="input-wrap"><MapPin/><input value={registerForm.city} onChange={e=>updateRegister('city',e.target.value)} required/></div></label><label>Teléfono / WhatsApp<div className="input-wrap"><Phone/><input type="tel" value={registerForm.phone} onChange={e=>updateRegister('phone',e.target.value)} required/></div></label><label className="auth-full">Nombre del propietario<div className="input-wrap"><User/><input value={registerForm.fullName} onChange={e=>updateRegister('fullName',e.target.value)} autoComplete="name" required/></div></label><label className="auth-full">Correo electrónico<div className="input-wrap"><Mail/><input type="email" value={registerForm.email} onChange={e=>updateRegister('email',e.target.value)} autoComplete="email" required/></div></label><label>Contraseña<div className="input-wrap"><KeyRound/><input type={show?'text':'password'} value={registerForm.password} onChange={e=>updateRegister('password',e.target.value)} autoComplete="new-password" minLength={12} required/></div><small className="field-help">Mínimo 12 caracteres, con letras y números.</small></label><label>Confirmar contraseña<div className="input-wrap"><ShieldCheck/><input type={show?'text':'password'} value={registerForm.confirmPassword} onChange={e=>updateRegister('confirmPassword',e.target.value)} autoComplete="new-password" minLength={12} required/><button type="button" className="text-button" onClick={()=>setShow(!show)}>{show?'Ocultar':'Ver'}</button></div></label></div><label className="terms-check"><input type="checkbox" checked={registerForm.terms} onChange={e=>updateRegister('terms',e.target.checked)}/><span>Acepto los términos de uso y el tratamiento de datos para crear la cuenta.</span></label>{error&&<p className="form-error">{error}</p>}<button className="primary-button login-button" disabled={loading}>{loading?<LoaderCircle className="spin"/>:<>Crear mi taller gratis <ChevronRight/></>}</button><p className="auth-footnote">Incluye 1 usuario, 20 órdenes al mes y 5 fotos por orden. ¿Ya tienes una cuenta? <button type="button" onClick={()=>changeMode('login')}>Inicia sesión</button></p></form>}
      {mode==='forgot'&&<form className="login-card" onSubmit={submitForgot}><button type="button" className="auth-back" onClick={()=>changeMode('login')}><ArrowLeft/>Volver al inicio</button><span className="welcome-icon"><Mail size={24}/></span><h2>Recupera tu acceso</h2><p>Te enviaremos un enlace seguro para crear una contraseña nueva.</p>{success?<><div className="auth-message success"><CheckCircle2/>{success}</div><button type="button" className="secondary-button auth-secondary" onClick={()=>changeMode('login')}>Volver a iniciar sesión</button></>:<><label>Correo de tu cuenta<div className="input-wrap"><Mail/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></div></label>{error&&<p className="form-error">{error}</p>}<button className="primary-button login-button" disabled={loading}>{loading?<LoaderCircle className="spin"/>:<>Enviar enlace de recuperación <ChevronRight/></>}</button></>}</form>}
      {mode==='reset'&&<form className="login-card" onSubmit={submitReset}><span className="welcome-icon"><KeyRound size={24}/></span><h2>Crea una nueva contraseña</h2><p>Elige una contraseña distinta a la anterior.</p><label>Nueva contraseña<div className="input-wrap"><KeyRound/><input type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password" minLength={12} required/><button type="button" className="text-button" onClick={()=>setShow(!show)}>{show?'Ocultar':'Ver'}</button></div></label><label>Confirmar contraseña<div className="input-wrap"><ShieldCheck/><input type={show?'text':'password'} value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} autoComplete="new-password" minLength={12} required/></div></label><small className="field-help standalone">Mínimo 12 caracteres, con letras y números.</small>{error&&<p className="form-error">{error}</p>}<button className="primary-button login-button" disabled={loading}>{loading?<LoaderCircle className="spin"/>:<>Guardar nueva contraseña <Check/></>}</button></form>}
    </section>
  </main>
}

const navigation:{label:string;page:Page;icon:LucideIcon}[]=[{label:'Inicio',page:'dashboard',icon:LayoutDashboard},{label:'Órdenes de taller',page:'orders',icon:ClipboardList},{label:'Clientes y vehículos',page:'customers',icon:Users},{label:'Cotizaciones',page:'quotes',icon:FileText},{label:'Ventas y facturas',page:'sales',icon:ReceiptText},{label:'Contabilidad',page:'accounting',icon:Calculator},{label:'Reportes',page:'reports',icon:TrendingUp},{label:'Planes y suscripción',page:'billing',icon:WalletCards}]

function Sidebar({page,setPage,open,close,logout,workshop,orderCount,user}:{page:Page;setPage:(p:Page)=>void;open:boolean;close:()=>void;logout:()=>void;workshop:Workshop;orderCount:number;user?:CurrentUser}){const display=user||{name:'Julián Sánchez',role:'Administrador'} as CurrentUser;return <><aside className={`sidebar ${open?'open':''}`}><div className="side-top"><Logo/><button className="mobile-close" onClick={close}><X/></button></div><div className="shop-chip"><div className="avatar shop">TM</div><span><b>{workshop.name}</b><small>Sede principal · {workshop.city}</small></span><ChevronDown size={16}/></div><nav>{navigation.map(item=><button key={item.page} className={page===item.page?'active':''} onClick={()=>{setPage(item.page);close()}}><item.icon size={19}/><span>{item.label}</span>{item.page==='orders'&&<i>{orderCount}</i>}</button>)}</nav><div className="side-bottom"><button className={page==='settings'?'active':''} onClick={()=>setPage('settings')}><Settings size={19}/>Configuración</button><button onClick={logout}><LogOut size={19}/>Cerrar sesión</button><div className="user-chip"><div className="avatar">{initials(display.name)}</div><span><b>{display.name}</b><small>{display.role}</small></span><span className="api-online"><i/> API</span></div></div></aside>{open&&<div className="sidebar-overlay" onClick={close}/>}</>}

function Header({title,subtitle,openMenu,onNew,search,setSearch}:{title:string;subtitle?:string;openMenu:()=>void;onNew:()=>void;search:string;setSearch:(v:string)=>void}){return <header className="topbar"><div className="title-row"><button className="menu-button" onClick={openMenu}><Menu/></button><div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div></div><div className="header-actions"><div className="global-search"><Search size={18}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar orden, cliente o placa..."/></div><button className="icon-button notification"><Bell size={19}/><i/></button><button className="primary-button" onClick={onNew}><Plus size={18}/>Nueva orden</button></div></header>}
function StatCard({label,value,note,icon:Icon,tone}:{label:string;value:string;note:string;icon:LucideIcon;tone:string}){return <div className="stat-card"><div className={`stat-icon ${tone}`}><Icon/></div><div className="stat-meta"><span>{label}</span><strong>{value}</strong><small>{note}</small></div></div>}
function StageBadge({stage}:{stage:Stage}){return <span className={`stage-badge s-${stage.replace(/ /g,'-').toLowerCase()}`}><i/>{stage}</span>}

function Dashboard({data,onOrder,onNew,onCustomer,setPage}:{data:Bootstrap;onOrder:(o:Order)=>void;onNew:()=>void;onCustomer:()=>void;setPage:(p:Page)=>void}){
  const active=data.orders.filter(o=>o.stage!=='Entrega'),diagnostic=data.orders.filter(o=>o.stage==='Diagnóstico').length,authorize=data.orders.filter(o=>o.stage==='Autorización').length,sales=data.invoices.reduce((s,x)=>s+x.total,0)
  return <div className="page-content"><div className="welcome-strip"><div><span>{new Intl.DateTimeFormat('es-CO',{dateStyle:'full'}).format(new Date())}</span><h2>Buenos días, Julián 👋</h2><p>La operación multiservicio de tu taller está conectada.</p></div><button className="secondary-button" onClick={()=>setPage('orders')}><CalendarClock/>Agenda operativa</button></div><section className="stats-grid"><StatCard label="Órdenes activas" value={String(active.length)} note={`${active.filter(o=>o.delivery.startsWith('Hoy')).length} por entregar hoy`} icon={ClipboardList} tone="orange"/><StatCard label="En diagnóstico" value={String(diagnostic)} note="Mecánica y carrocería" icon={Gauge} tone="purple"/><StatCard label="Por autorizar" value={String(authorize)} note={money(data.orders.filter(o=>o.stage==='Autorización').reduce((s,o)=>s+o.value,0))} icon={Clock3} tone="amber"/><StatCard label="Ventas registradas" value={money(sales)} note={`${data.invoices.length} facturas`} icon={CircleDollarSign} tone="green"/></section><section className="dashboard-grid"><div className="panel orders-panel"><div className="panel-heading"><div><h3>Órdenes en proceso</h3><p>Información guardada en el backend</p></div><button className="link-button" onClick={()=>setPage('orders')}>Ver todas <ChevronRight/></button></div><div className="order-list">{active.slice(0,5).map(order=><button className="order-row" key={order.id} onClick={()=>onOrder(order)}><div className="car-icon" style={{'--accent':order.color} as React.CSSProperties}>{order.serviceArea.includes('pintura')?<Paintbrush/>:<Car/>}</div><div className="order-main"><div><b>{order.id}</b><StageBadge stage={order.stage}/></div><strong>{order.car}</strong><small>{order.customer} · {order.plate} · {order.serviceArea}</small></div><div className="order-progress"><div><span>Progreso</span><b>{order.progress}%</b></div><div className="progress-track"><i style={{width:`${order.progress}%`,background:order.color}}/></div><small><Clock3/> {order.delivery}</small></div><ChevronRight className="row-arrow"/></button>)}</div></div><div className="panel today-panel"><div className="panel-heading"><div><h3>Áreas del taller</h3><p>Servicios configurados</p></div></div><div className="service-area-list">{serviceAreas.slice(0,6).map((area,i)=><button key={area} onClick={()=>setPage('orders')}><span className={`service-dot t${i}`}>{area.includes('pintura')?<Paintbrush/>:<Wrench/>}</span><b>{area}</b><small>{data.orders.filter(o=>o.serviceArea===area).length} órdenes</small><ChevronRight/></button>)}</div></div></section><section className="bottom-grid"><div className="panel attention-panel"><div className="panel-heading"><div><h3>Resumen persistente</h3><p>Los registros sobreviven al recargar</p></div></div><div className="attention-items"><div><span className="mini-icon amber"><Users/></span><p><b>{data.customers.length} clientes</b><small>{data.customers.reduce((s,c)=>s+c.vehicles.length,0)} vehículos</small></p><button onClick={()=>setPage('customers')}>Revisar</button></div><div><span className="mini-icon red"><Activity/></span><p><b>{data.expenses.length} gastos</b><small>{money(data.expenses.reduce((s,x)=>s+x.amount,0))}</small></p><button onClick={()=>setPage('accounting')}>Ver contabilidad</button></div><div><span className="mini-icon blue"><MessageCircle/></span><p><b>WhatsApp manual activo</b><small>Mensajes prellenados</small></p><button onClick={()=>onOrder(active[0])}>Probar</button></div></div></div><div className="panel quick-panel"><div className="panel-heading"><div><h3>Acciones rápidas</h3><p>Flujos funcionales</p></div></div><div className="quick-actions"><button onClick={onNew}><span><Plus/></span>Nueva orden</button><button onClick={onCustomer}><span><UserPlus/></span>Nuevo cliente</button><button onClick={()=>setPage('quotes')}><span><FileText/></span>Cotizaciones</button><button onClick={()=>setPage('sales')}><span><ReceiptText/></span>Facturas</button></div></div></section></div>
}

function OrdersPage({orders,onOpen,onNew}:{orders:Order[];onOpen:(o:Order)=>void;onNew:()=>void}){const[filter,setFilter]=useState('Todas');const shown=filter==='Todas'?orders:orders.filter(o=>o.serviceArea===filter||o.stage===filter);return <div className="page-content"><div className="page-lead"><div><h2>Órdenes de taller</h2><p>Mecánica, pintura y demás servicios automotrices.</p></div><button className="primary-button" onClick={onNew}><Plus/>Nueva orden</button></div><div className="filter-bar"><div className="filter-tabs">{['Todas','Mecánica general','Latonería y pintura','Electricidad automotriz','Reparación'].map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{f}</button>)}</div></div><div className="panel table-panel"><table className="data-table"><thead><tr><th>Orden / vehículo</th><th>Área</th><th>Cliente</th><th>Estado</th><th>Técnico</th><th>Valor</th><th/></tr></thead><tbody>{shown.map(o=><tr key={o.id} onClick={()=>onOpen(o)}><td><div className="vehicle-cell"><span className="car-icon small" style={{'--accent':o.color} as React.CSSProperties}><Car/></span><span><b>{o.id} · {o.plate}</b><small>{o.car}</small></span></div></td><td><b>{o.serviceArea}</b>{o.paintColor&&<small>Color: {o.paintColor}</small>}</td><td><b>{o.customer}</b><small>{o.phone}</small></td><td><StageBadge stage={o.stage}/><div className="tiny-progress"><i style={{width:`${o.progress}%`}}/></div></td><td>{o.tech}</td><td><b>{money(o.value)}</b></td><td><ChevronRight/></td></tr>)}</tbody></table></div></div>}

function CustodyEditor({order,onSaved,notify}:{order:Order;onSaved:()=>void;notify:(m:string,t?:'ok'|'error')=>void}){
  const[arrivalContact,setArrivalContact]=useState(order.arrivalContact||''),[deliveryContact,setDeliveryContact]=useState(order.deliveryContact||''),[busy,setBusy]=useState(false)
  useEffect(()=>{setArrivalContact(order.arrivalContact||'');setDeliveryContact(order.deliveryContact||'')},[order.id,order.arrivalContact,order.deliveryContact])
  const changed=arrivalContact.trim()!==(order.arrivalContact||'')||deliveryContact.trim()!==(order.deliveryContact||'')
  const save=async()=>{setBusy(true);try{await api.updateOrder(order.id,{arrivalContact,deliveryContact});onSaved();notify('Responsables de entrega y retiro guardados')}catch(err){notify(err instanceof Error?err.message:'No fue posible guardar','error')}finally{setBusy(false)}}
  return <div className="custody-editor"><div className="custody-editor-head"><div><b>Custodia del vehículo</b><small>Datos opcionales para entrega, retiro y futuras garantías.</small></div><ShieldCheck/></div><div className="custody-fields"><label>¿Quién entregó el vehículo?<input value={arrivalContact} onChange={e=>setArrivalContact(e.target.value)} maxLength={180} placeholder="Nombre, parentesco o identificación"/></label><label>¿Quién retiró el vehículo?<input value={deliveryContact} onChange={e=>setDeliveryContact(e.target.value)} maxLength={180} placeholder="Se puede completar al momento de la entrega"/></label></div><button className="secondary-button" onClick={save} disabled={busy||!changed}>{busy?<LoaderCircle className="spin"/>:<Check/>}Guardar responsables</button></div>
}

function EvidenceGallery({order,onUploaded,notify}:{order:Order;onUploaded:(items:Evidence[])=>void;notify:(m:string,t?:'ok'|'error')=>void}){
  const input=useRef<HTMLInputElement>(null),[busy,setBusy]=useState(false)
  const demos=order.evidence.length?order.evidence:[{id:'d1',url:'/evidence-front.svg',name:'Ingreso frontal',type:'Antes',caption:'',at:'',author:''},{id:'d2',url:'/evidence-wheel.svg',name:'Inspección',type:'Antes',caption:'',at:'',author:''},{id:'d3',url:'/evidence-interior.svg',name:'Interior',type:'Ingreso',caption:'',at:'',author:''}]
  const upload=async(e:React.ChangeEvent<HTMLInputElement>)=>{const files=Array.from(e.target.files||[]);if(!files.length)return;setBusy(true);try{onUploaded(await api.uploadEvidence(order.id,files,'Proceso'));notify(`${files.length} evidencia(s) guardada(s)`)}catch(err){notify(err instanceof Error?err.message:'Error al subir','error')}finally{setBusy(false);e.target.value=''}}
  return <><CustodyEditor order={order} onSaved={()=>onUploaded([])} notify={notify}/><div className="evidence-grid">{demos.map((ev,i)=><div className="evidence-photo" key={ev.id}><img src={ev.url} alt={ev.name}/><span>{ev.type||(['Antes','Proceso','Después'][i%3])}</span></div>)}<button className="upload-card" onClick={()=>input.current?.click()} disabled={busy}>{busy?<LoaderCircle className="spin"/>:<Upload/>}<b>{busy?'Guardando...':'Agregar evidencia'}</b><small>Máx. 10 MB</small></button><input ref={input} hidden multiple type="file" accept="image/*" onChange={upload}/></div></>
}

function QuoteEditor({order,onUpdated,onPdf,onWhatsApp,notify}:{order:Order;onUpdated:(o:Order)=>void;onPdf:()=>Promise<void>;onWhatsApp:()=>Promise<void>;notify:(m:string,t?:'ok'|'error')=>void}){const defaults=order.serviceArea==='Latonería y pintura'?[{id:'p1',name:'Preparación y latonería de panel',type:'Servicio',qty:1,price:480000},{id:'p2',name:'Pintura y materiales',type:'Servicio',qty:1,price:720000}]:[{id:'m1',name:'Diagnóstico técnico',type:'Servicio',qty:1,price:180000},{id:'m2',name:'Mano de obra especializada',type:'Servicio',qty:1,price:360000}];const[items,setItems]=useState<QuoteItem[]>(order.quote.items.length?order.quote.items:defaults);const[status,setStatus]=useState(order.quote.status||'Borrador');const[busy,setBusy]=useState(false);const subtotal=items.reduce((s,x)=>s+Number(x.qty)*Number(x.price),0),tax=Math.round(subtotal*.19);const save=async()=>{setBusy(true);try{const quote=await api.updateQuote(order.id,{items,status,taxRate:19});onUpdated({...order,quote,value:subtotal+tax});notify('Cotización guardada')}catch(err){notify(err instanceof Error?err.message:'Error','error')}finally{setBusy(false)}};const change=(i:number,key:keyof QuoteItem,value:string|number)=>setItems(items.map((x,n)=>n===i?{...x,[key]:value}:x));return <div className="quote-layout"><div className="panel quote-document"><div className="quote-top"><div><Logo/><p>NIT 90234566<br/>Cra. 6 #32-4 · Montería · 300 290 2939</p></div><div><span>COTIZACIÓN</span><b>{order.id}</b><select value={status} onChange={e=>setStatus(e.target.value)}><option>Borrador</option><option>Enviada</option><option>Autorizada</option><option>Rechazada</option></select></div></div><div className="quote-parties"><div><span>CLIENTE</span><b>{order.customer}</b><p>{order.phone}</p></div><div><span>VEHÍCULO / SERVICIO</span><b>{order.car}</b><p>{order.plate} · {order.serviceArea}</p></div></div><table className="quote-edit-table"><thead><tr><th>Descripción</th><th>Cant.</th><th>Valor unit.</th><th>Total</th><th/></tr></thead><tbody>{items.map((item,i)=><tr key={item.id}><td><input value={item.name} onChange={e=>change(i,'name',e.target.value)}/><small>{item.type}</small></td><td><input type="number" min="1" value={item.qty} onChange={e=>change(i,'qty',Number(e.target.value))}/></td><td><input type="number" min="0" value={item.price} onChange={e=>change(i,'price',Number(e.target.value))}/></td><td>{money(item.qty*item.price)}</td><td><button onClick={()=>setItems(items.filter((_,n)=>n!==i))}><X/></button></td></tr>)}</tbody></table><button className="add-task" onClick={()=>setItems([...items,{id:`q_${Date.now()}`,name:'Nuevo concepto',type:'Servicio',qty:1,price:0}])}><Plus/>Agregar pieza, material o servicio</button><div className="quote-total"><div><p><ShieldCheck/>Documento generado por Taller Motor Pro.</p></div><dl><div><dt>Subtotal</dt><dd>{money(subtotal)}</dd></div><div><dt>IVA (19%)</dt><dd>{money(tax)}</dd></div><div><dt>Total</dt><dd>{money(subtotal+tax)}</dd></div></dl></div></div><aside className="quote-actions panel"><FileCheck2/><h3>{status}</h3><p>Guarda los cambios antes de descargar o enviar.</p><button className="primary-button" onClick={save} disabled={busy}>{busy?<LoaderCircle className="spin"/>:<Check/>}Guardar</button><button className="secondary-button" onClick={onPdf}><Download/>Descargar PDF</button><button className="secondary-button" onClick={onWhatsApp}><MessageCircle/>Enviar por WhatsApp</button></aside></div>}

function OrderDetail({order,update,refresh,back,notify}:{order:Order;update:(o:Order)=>Promise<void>;refresh:()=>Promise<void>;back:()=>void;notify:(m:string,t?:'ok'|'error')=>void}){const[tab,setTab]=useState<'process'|'quote'|'notes'|'history'>('process');const[note,setNote]=useState('');const[busy,setBusy]=useState(false);const current=stages.indexOf(order.stage);const advance=async()=>{if(current>=stages.length-1)return;setBusy(true);try{await update({...order,stage:stages[current+1],progress:Math.round((current+2)/stages.length*100)});notify(`Orden avanzada a ${stages[current+1]}`)}catch(err){notify(err instanceof Error?err.message:'Error','error')}finally{setBusy(false)}};const whatsapp=async()=>{const popup=window.open('about:blank','_blank');try{const r=await api.whatsapp(order.id);if(popup)popup.location.href=r.url;else window.location.href=r.url;notify('Conversación de WhatsApp preparada')}catch(err){popup?.close();notify(err instanceof Error?err.message:'Error','error')}};const sendNote=async()=>{if(!note.trim())return;setBusy(true);try{await api.addNote(order.id,note);setNote('');await refresh();notify('Nota guardada')}catch(err){notify(err instanceof Error?err.message:'Error','error')}finally{setBusy(false)}};return <div className="page-content detail-content"><button className="back-button" onClick={back}><ChevronLeft/>Volver a órdenes</button><div className="detail-hero"><div className="detail-title"><div className="car-icon large" style={{'--accent':order.color} as React.CSSProperties}>{order.serviceArea.includes('pintura')?<Paintbrush/>:<Car/>}</div><div><div><span className="order-code">{order.id}</span><StageBadge stage={order.stage}/></div><h2>{order.car}</h2><p>{order.customer} · <span>{order.plate}</span> · {order.serviceArea}</p></div></div><div className="detail-actions"><button className="secondary-button" onClick={whatsapp}><MessageCircle/>WhatsApp</button><button className="secondary-button" onClick={()=>api.downloadQuote(order.id).catch(e=>notify(e.message,'error'))}><Download/>PDF</button><button className="primary-button" onClick={advance} disabled={busy||current===stages.length-1}>{busy?<LoaderCircle className="spin"/>:<>Avanzar etapa <ChevronRight/></>}</button></div></div><div className="stage-flow">{stages.map((s,i)=><div className={i<current?'complete':i===current?'current':''} key={s}><span>{i<current?<Check/>:i+1}</span><b>{s}</b>{i<stages.length-1&&<i/>}</div>)}</div><div className="detail-tabs"><button className={tab==='process'?'active':''} onClick={()=>setTab('process')}><Wrench/>Proceso y evidencias</button><button className={tab==='quote'?'active':''} onClick={()=>setTab('quote')}><FileText/>Cotización</button><button className={tab==='notes'?'active':''} onClick={()=>setTab('notes')}><MessageCircle/>Notas <span>{order.notes.length}</span></button><button className={tab==='history'?'active':''} onClick={()=>setTab('history')}><History/>Historial</button></div>{tab==='process'&&<div className="detail-grid"><div className="detail-main"><section className="panel detail-section"><div className="section-head"><div><span className="section-number done"><Check/></span><div><h3>Recepción e inspección inicial</h3><p>Información persistida en la orden</p></div></div></div><div className="inspection-summary"><div><span>Kilometraje</span><b>{order.mileage.toLocaleString('es-CO')} km</b></div><div><span>Combustible</span><b>{order.fuel}</b></div><div><span>Área de servicio</span><b>{order.serviceArea}</b></div><div><span>Elementos recibidos</span><b>{order.receivedItems}</b></div></div><p className="section-note"><b>Motivo de ingreso</b>{order.reason||'Sin observaciones'}</p>{order.serviceArea==='Latonería y pintura'&&<div className="paint-summary"><Paintbrush/><div><b>Trabajo de carrocería</b><span>Color: {order.paintColor||'Por definir'} · Zonas: {order.affectedAreas?.join(', ')||'Por registrar'}</span></div></div>}<h4>Evidencias <span>{order.evidence.length} guardadas</span></h4><EvidenceGallery order={order} onUploaded={async()=>{await refresh()}} notify={notify}/></section><section className="panel detail-section active-section"><div className="section-head"><div><span className="section-number">{current+1}</span><div><h3>{order.stage} en proceso</h3><p>Responsable: {order.tech}</p></div></div><span className="live-pill"><i/>Actualización en vivo</span></div><div className="job-card current-job"><div className="job-check">{order.serviceArea.includes('pintura')?<Paintbrush/>:<Wrench/>}</div><div><b>{order.serviceArea}</b><p>{order.reason}</p><div className="job-progress"><i style={{width:`${order.progress}%`}}/></div></div><span>{order.progress}%</span></div></section></div><aside className="detail-aside"><section className="panel customer-card"><div className="section-head"><h3>Cliente</h3></div><div className="customer-info"><div className="avatar customer">{initials(order.customer)}</div><div><b>{order.customer}</b><span>{order.plate}</span></div></div><div className="contact-line"><Phone/>{order.phone}</div><button className="secondary-button full" onClick={whatsapp}><MessageCircle/>Abrir conversación</button></section><section className="panel workshop-info"><h3>Información de la orden</h3><dl><div><dt>Técnico</dt><dd>{order.tech}</dd></div><div><dt>Entrega</dt><dd>{order.delivery}</dd></div><div><dt>Valor</dt><dd className="money">{money(order.value)}</dd></div><div><dt>Evidencias</dt><dd>{order.evidence.length}</dd></div></dl></section><section className="whatsapp-card"><div><MessageCircle/><span><b>WhatsApp disponible</b><small>Abre el chat con mensaje prellenado</small></span></div><button onClick={whatsapp}>Preparar actualización <Send/></button></section></aside></div>}{tab==='quote'&&<QuoteEditor order={order} onUpdated={async()=>refresh()} onPdf={()=>api.downloadQuote(order.id)} onWhatsApp={whatsapp} notify={notify}/>} {tab==='notes'&&<div className="panel notes-panel"><div className="panel-heading"><div><h3>Notas del proceso</h3><p>Guardadas en el backend</p></div></div><div className="notes-feed">{order.notes.map(n=><div className="note-item" key={n.id}><div className="avatar">{initials(n.author)}</div><div><div><b>{n.author}</b><span>{n.role} · {dateText(n.at)}</span></div><p>{n.text}</p></div></div>)}</div><div className="note-composer"><div className="avatar">JS</div><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Escribe una nota..."/><button className="primary-button" onClick={sendNote} disabled={busy}><Send/>Guardar</button></div></div>}{tab==='history'&&<div className="panel history-panel">{[...order.history].reverse().map((h,i)=><div key={h.id}><span className={i===0?'current':''}>{i===0?<Activity/>:<Check/>}</span><p><b>{h.event}</b><small>{h.author} · {dateText(h.at)}</small></p></div>)}</div>}</div>}

const normalizedPlate=(plate:string)=>String(plate||'').replace(/[^A-Za-z0-9]/g,'').toUpperCase()

function VehicleHistoryModal({customer,vehicle,orders,close,onOpenOrder}:{customer:Customer;vehicle:Vehicle;orders:Order[];close:()=>void;onOpenOrder:(order:Order)=>void}){
  const vehicleOrders=orders.filter(order=>order.vehicleId===vehicle.id||normalizedPlate(order.plate)===normalizedPlate(vehicle.plate)).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')))
  const lastMileage=Math.max(vehicle.mileage||0,...vehicleOrders.map(order=>order.mileage||0))
  return <div className="modal-overlay"><div className="modal vehicle-history-modal"><div className="modal-head"><div><span className="modal-icon"><History/></span><div><h3>Historial del vehículo · {vehicle.plate}</h3><p>{vehicle.brand} {vehicle.model} {vehicle.year} · Propietario: {customer.name}</p></div></div><button className="icon-button" onClick={close}><X/></button></div><div className="vehicle-history-summary"><div><span>Visitas registradas</span><b>{vehicleOrders.length}</b></div><div><span>Último kilometraje</span><b>{lastMileage.toLocaleString('es-CO')} km</b></div><div><span>Valor histórico</span><b>{money(vehicleOrders.reduce((sum,order)=>sum+order.value,0))}</b></div></div><div className="vehicle-history-list">{vehicleOrders.length?vehicleOrders.map(order=><article className="vehicle-history-order" key={order.id}><div className="vehicle-history-head"><div><b>{order.id}</b><StageBadge stage={order.stage}/></div><time>{dateText(order.createdAt||order.history[0]?.at)}</time></div><div className="vehicle-history-main"><span><Wrench/> {order.serviceArea}</span><span><Gauge/> {order.mileage.toLocaleString('es-CO')} km</span><span><CircleDollarSign/> {money(order.value)}</span></div><p><b>Motivo:</b> {order.reason||'Sin información'}</p>{(order.finalDiagnosis||order.diagnosis)&&<p><b>Diagnóstico:</b> {order.finalDiagnosis||order.diagnosis}</p>}{order.quote.items.length>0&&<div className="history-services"><b>Repuestos y servicios</b>{order.quote.items.map(item=><span key={item.id}>{item.qty} × {item.name}</span>)}</div>}{(order.arrivalContact||order.deliveryContact)&&<div className="custody-history"><span><b>Entregó:</b> {order.arrivalContact||'No registrado'}</span><span><b>Retiró:</b> {order.deliveryContact||'No registrado'}</span></div>}<button className="secondary-button" onClick={()=>onOpenOrder(order)}>Abrir orden completa <ChevronRight/></button></article>):<div className="empty-history"><Car/><b>Aún no hay visitas registradas</b><p>Las próximas órdenes de esta placa aparecerán automáticamente aquí.</p></div>}</div></div></div>
}

function CustomersPage({customers,orders,onAdd,onOpenOrder}:{customers:Customer[];orders:Order[];onAdd:()=>void;onOpenOrder:(order:Order)=>void}){
  const[q,setQ]=useState(''),[selected,setSelected]=useState<{customer:Customer;vehicle:Vehicle}|null>(null)
  const shown=customers.filter(c=>`${c.name} ${c.document} ${c.phone} ${c.vehicles.map(v=>v.plate).join(' ')}`.toLowerCase().includes(q.toLowerCase()))
  return <div className="page-content"><div className="page-lead"><div><h2>Clientes y vehículos</h2><p>Busca una placa y abre su historial para garantías o visitas anteriores.</p></div><button className="primary-button" onClick={onAdd}><UserPlus/>Nuevo cliente</button></div><div className="customer-stats"><div><Users/><span><b>{customers.length}</b><small>Clientes registrados</small></span></div><div><Car/><span><b>{customers.reduce((s,c)=>s+c.vehicles.length,0)}</b><small>Vehículos vinculados</small></span></div><div><History/><span><b>{orders.length}</b><small>Visitas en el historial</small></span></div></div><div className="panel table-panel"><div className="table-tools"><div className="local-search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar por nombre, documento o placa..."/></div></div><table className="data-table"><thead><tr><th>Cliente</th><th>Documento</th><th>Vehículos e historial</th><th>Órdenes</th><th>Facturado</th></tr></thead><tbody>{shown.map(c=><tr key={c.id}><td><div className="person-cell"><span className="avatar customer">{initials(c.name)}</span><span><b>{c.name}</b><small>{c.phone} · {c.email}</small></span></div></td><td>{c.documentType} {c.document}</td><td>{c.vehicles.map(v=><button className="vehicle-pill history-link" key={v.id} onClick={()=>setSelected({customer:c,vehicle:v})}>{v.brand} {v.model} · <b>{v.plate}</b><History/></button>)}</td><td><b>{orders.filter(o=>o.customerId===c.id).length}</b></td><td><b>{money(orders.filter(o=>o.customerId===c.id).reduce((s,o)=>s+o.value,0))}</b></td></tr>)}</tbody></table></div>{selected&&<VehicleHistoryModal customer={selected.customer} vehicle={selected.vehicle} orders={orders} close={()=>setSelected(null)} onOpenOrder={order=>{setSelected(null);onOpenOrder(order)}}/>}</div>
}

function QuotesPage({orders,onOpen}:{orders:Order[];onOpen:(o:Order)=>void}){const rows=orders.filter(o=>o.quote.items.length||o.stage==='Cotización'||o.stage==='Autorización');return <div className="page-content"><div className="page-lead"><div><h2>Cotizaciones</h2><p>Edita, descarga y envía cotizaciones asociadas a órdenes.</p></div></div><div className="panel table-panel"><table className="data-table"><thead><tr><th>Orden</th><th>Cliente</th><th>Servicio</th><th>Estado</th><th>Total</th><th/></tr></thead><tbody>{rows.map(o=><tr key={o.id} onClick={()=>onOpen(o)}><td><b>{o.id}</b><small>{o.plate}</small></td><td><b>{o.customer}</b></td><td>{o.serviceArea}</td><td><span className="status-pill">{o.quote.status}</span></td><td><b>{money(o.value)}</b></td><td><ChevronRight/></td></tr>)}</tbody></table>{!rows.length&&<div className="empty-feature"><FileText/><h3>No hay cotizaciones</h3><p>Abre una orden y crea sus conceptos.</p></div>}</div></div>}

function SalesPage({invoices,orders,onNew}:{invoices:Invoice[];orders:Order[];onNew:()=>void}){return <div className="page-content"><div className="page-lead"><div><h2>Ventas y facturas</h2><p>Facturas de demostración y próximos mantenimientos.</p></div><button className="primary-button" onClick={onNew}><Plus/>Nueva factura</button></div><section className="stats-grid"><StatCard label="Facturado" value={money(invoices.reduce((s,x)=>s+x.total,0))} note={`${invoices.length} documentos`} icon={ReceiptText} tone="green"/><StatCard label="Órdenes listas" value={String(orders.filter(o=>o.stage==='Entrega').length)} note="Disponibles para facturar" icon={CheckCircle2} tone="purple"/><StatCard label="Próximos mantenimientos" value={String(invoices.filter(x=>x.nextMaintenance).length)} note="Recordatorios registrados" icon={CalendarClock} tone="amber"/><StatCard label="Ticket promedio" value={money(invoices.length?invoices.reduce((s,x)=>s+x.total,0)/invoices.length:0)} note="Promedio de ventas" icon={TrendingUp} tone="orange"/></section><div className="panel table-panel"><table className="data-table"><thead><tr><th>Factura</th><th>Cliente</th><th>Orden</th><th>Fecha</th><th>Próximo mantenimiento</th><th>Total</th></tr></thead><tbody>{invoices.map(i=><tr key={i.id}><td><b>{i.id}</b><small>{i.status}</small></td><td><b>{i.customer}</b></td><td>{i.orderId}</td><td>{i.date}</td><td>{i.nextMaintenance||'Por definir'}</td><td><b>{money(i.total)}</b></td></tr>)}</tbody></table></div></div>}

function AccountingPage({expenses,invoices,onExpense}:{expenses:Expense[];invoices:Invoice[];onExpense:()=>void}){const income=invoices.reduce((s,x)=>s+x.total,0),cost=expenses.reduce((s,x)=>s+x.amount,0);return <div className="page-content"><div className="page-lead"><div><h2>Contabilidad básica</h2><p>Calculada desde ventas y gastos persistentes.</p></div><button className="primary-button" onClick={onExpense}><Plus/>Registrar gasto</button></div><section className="stats-grid"><StatCard label="Ingresos" value={money(income)} note="Facturas registradas" icon={CircleDollarSign} tone="green"/><StatCard label="Gastos" value={money(cost)} note={`${expenses.length} movimientos`} icon={WalletCards} tone="orange"/><StatCard label="Utilidad estimada" value={money(income-cost)} note="Antes de impuestos" icon={TrendingUp} tone="purple"/><StatCard label="IVA estimado" value={money(Math.round(income*19/119))} note="Referencia demo" icon={Calculator} tone="amber"/></section><div className="panel table-panel"><div className="panel-heading"><div><h3>Movimientos de gasto</h3><p>Registro operativo</p></div></div><table className="data-table"><thead><tr><th>Fecha</th><th>Categoría</th><th>Descripción</th><th>Valor</th></tr></thead><tbody>{expenses.map(e=><tr key={e.id}><td>{e.date}</td><td><span className="status-pill">{e.category}</span></td><td><b>{e.description}</b></td><td><b>{money(e.amount)}</b></td></tr>)}</tbody></table></div></div>}

function ReportsPage({data}:{data:Bootstrap}){const delivered=data.orders.filter(o=>o.stage==='Entrega').length,active=data.orders.filter(o=>o.stage!=='Entrega').length;const byArea=serviceAreas.map(a=>({a,count:data.orders.filter(o=>o.serviceArea===a).length})).filter(x=>x.count);return <div className="page-content"><div className="page-lead"><div><h2>Reportes del taller</h2><p>Indicadores calculados con los datos de la demo.</p></div></div><div className="report-grid"><div className="panel report-card"><span className="report-icon orange"><Wrench/></span><div><h3>Órdenes activas</h3><strong>{active}</strong><p>En todas las áreas</p></div></div><div className="panel report-card"><span className="report-icon green"><CheckCircle2/></span><div><h3>Entregadas</h3><strong>{delivered}</strong><p>Trabajos finalizados</p></div></div><div className="panel report-card"><span className="report-icon purple"><CircleDollarSign/></span><div><h3>Valor en órdenes</h3><strong>{money(data.orders.reduce((s,o)=>s+o.value,0))}</strong><p>Cotizado/autorizado</p></div></div></div><div className="panel report-table"><div className="panel-heading"><div><h3>Operación por área</h3><p>Distribución multiservicio</p></div></div><table className="data-table"><thead><tr><th>Área</th><th>Órdenes</th><th>Valor asociado</th><th>Participación</th></tr></thead><tbody>{byArea.map(x=><tr key={x.a}><td><b>{x.a}</b></td><td>{x.count}</td><td><b>{money(data.orders.filter(o=>o.serviceArea===x.a).reduce((s,o)=>s+o.value,0))}</b></td><td>{Math.round(x.count/data.orders.length*100)}%</td></tr>)}</tbody></table></div></div>}

function BillingPage({notify}:{notify:(m:string,t?:'ok'|'error')=>void}){
  const[plans,setPlans]=useState<Plan[]>([]),[billing,setBilling]=useState<'monthly'|'annual'>('monthly'),[account,setAccount]=useState<any>(null),[pending,setPending]=useState<string|null>(null),[busy,setBusy]=useState('')
  const load=async()=>{try{const[p,a]=await Promise.all([api.plans(),api.subscription()]);setPlans(p);setAccount(a)}catch(err){notify(err instanceof Error?err.message:'No fue posible cargar los planes','error')}}
  useEffect(()=>{void load()},[])
  const checkout=async(planId:string)=>{setBusy(planId);try{const result=await api.checkout(planId,billing);if(result.mode==='wompi'){window.location.assign(result.checkoutUrl);return}setPending(result.reference);notify('Pago de prueba creado. Confirma la simulación para activar el plan.')}catch(err){notify(err instanceof Error?err.message:'No fue posible iniciar el pago','error')}finally{setBusy('')}}
  const confirm=async()=>{if(!pending)return;setBusy('confirm');try{await api.confirmDemoPayment(pending);setPending(null);await load();notify('Plan activado en modo demostración')}catch(err){notify(err instanceof Error?err.message:'No fue posible confirmar','error')}finally{setBusy('')}}
  return <div className="page-content">
    <div className="page-lead"><div><h2>Planes y suscripción</h2><p>Empieza gratis y mejora cuando tu operación necesite más capacidad.</p></div><div className="billing-toggle"><button className={billing==='monthly'?'active':''} onClick={()=>setBilling('monthly')}>Mensual</button><button className={billing==='annual'?'active':''} onClick={()=>setBilling('annual')}>Anual <span>2 meses gratis</span></button></div></div>
    {account&&<><div className="subscription-banner"><ShieldCheck/><div><b>Plan actual: {account.plan?.name||'Gratis'}</b><small>{account.subscription?.planId==='gratis'?'Gratis para siempre · mejora cuando alcances tus límites':account.subscription?.currentPeriodEndsAt?`Vigente hasta ${new Date(account.subscription.currentPeriodEndsAt).toLocaleDateString('es-CO')}`:`Estado: ${account.subscription?.status}`}</small></div></div>{account.plan&&<div className="usage-panel panel"><div><span>Usuarios</span><b>{account.usage?.users||0} de {account.plan.limits.users}</b><i><em style={{width:`${Math.min(100,(account.usage?.users||0)/account.plan.limits.users*100)}%`}}/></i></div><div><span>Órdenes de este mes</span><b>{account.usage?.monthlyOrders||0} de {account.plan.limits.monthlyOrders}</b><i><em style={{width:`${Math.min(100,(account.usage?.monthlyOrders||0)/account.plan.limits.monthlyOrders*100)}%`}}/></i></div><p>Al llegar al límite conservas toda tu información y puedes ampliar la capacidad desde esta página.</p></div>}</>}
    {pending&&<div className="demo-payment"><div><b>Checkout creado en modo demostración</b><small>Referencia {pending}. En producción esta aprobación solo llega desde el webhook firmado de Wompi.</small></div><button className="primary-button" onClick={confirm} disabled={busy==='confirm'}>{busy==='confirm'?<LoaderCircle className="spin"/>:<Check/>}Simular pago aprobado</button></div>}
    <div className="plans-grid">{plans.map(plan=>{const price=billing==='annual'?plan.annualPrice:plan.monthlyPrice,current=account?.subscription?.planId===plan.id,isFree=plan.id==='gratis';return <article className={`plan-card panel ${plan.recommended?'featured':''} ${current?'current-plan':''}`} key={plan.id}>{plan.recommended&&<span className="recommended">Más elegido</span>}{current&&<span className="current-label">Tu plan</span>}<div className="plan-head"><span className="plan-icon"><WalletCards/></span><h3>{plan.name}</h3><p>{plan.description}</p></div><div className="plan-price"><strong>{isFree?'Gratis':money(price)}</strong><span>{isFree?'para siempre':`/${billing==='annual'?'año':'mes'}`}</span>{billing==='annual'&&!isFree&&<small>equivale a {money(Math.round(price/12))}/mes</small>}</div><ul>{plan.features.map(feature=><li key={feature}><CheckCircle2/>{feature}</li>)}</ul><div className="plan-limits"><span><Users/>{plan.limits.users} usuario{plan.limits.users===1?'':'s'}</span><span><ClipboardList/>{plan.limits.monthlyOrders} órdenes/mes</span><span><Camera/>{plan.limits.evidencePerOrder} fotos/orden</span><span><Camera/>{plan.limits.storageGb} GB</span></div><button className={plan.recommended?'primary-button':'secondary-button'} disabled={busy===plan.id||isFree} onClick={()=>checkout(plan.id)}>{busy===plan.id?<LoaderCircle className="spin"/>:isFree?(current?'Plan actual':'Incluido al registrarte'):current?'Renovar o cambiar período':'Mejorar a este plan'}</button></article>})}</div>
    <p className="pricing-note">El plan Gratis no vence. Los límites bloquean únicamente nuevas altas; los datos existentes se conservan para que el taller pueda mejorar su plan sin perder información.</p>
  </div>
}

function SettingsPage({workshop,onReset,notify}:{workshop:Workshop;onReset:()=>Promise<void>;notify:(m:string,t?:'ok'|'error')=>void}){
  const[tab,setTab]=useState<'workshop'|'users'|'integrations'|'security'>('workshop'),[usersList,setUsersList]=useState<any[]>([]),[busy,setBusy]=useState(false),[form,setForm]=useState({name:'',email:'',role:'Técnico',password:''})
  const loadUsers=async()=>{try{setUsersList(await api.users())}catch(err){notify(err instanceof Error?err.message:'No fue posible cargar usuarios','error')}}
  useEffect(()=>{if(tab==='users')void loadUsers()},[tab])
  const createUser=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await api.createUser(form);setForm({name:'',email:'',role:'Técnico',password:''});await loadUsers();notify('Usuario creado con su rol')}catch(err){notify(err instanceof Error?err.message:'No fue posible crear el usuario','error')}finally{setBusy(false)}}
  return <div className="page-content"><div className="page-lead"><div><h2>Configuración</h2><p>Datos, equipo e integraciones de {workshop.name}.</p></div><button className="secondary-button" onClick={onReset}><RefreshCcw/>Reiniciar demo</button></div><div className="settings-layout"><nav className="panel settings-nav"><button className={tab==='workshop'?'active':''} onClick={()=>setTab('workshop')}><Settings/>Datos del taller</button><button className={tab==='users'?'active':''} onClick={()=>setTab('users')}><Users/>Usuarios y roles</button><button className={tab==='integrations'?'active':''} onClick={()=>setTab('integrations')}><MessageCircle/>Integraciones</button><button className={tab==='security'?'active':''} onClick={()=>setTab('security')}><ShieldCheck/>Seguridad</button></nav><div className="panel settings-main">{tab==='workshop'&&<><h3>{workshop.name}</h3><p>NIT {workshop.nit} · {workshop.address}, {workshop.city} · {workshop.phone} · {workshop.email}</p><div className="info-grid"><div><span>Actividad</span><b>{workshop.businessType}</b></div><div><span>Ciudad</span><b>{workshop.city}</b></div><div><span>WhatsApp</span><b>{workshop.phone}</b></div></div></>}{tab==='users'&&<><h3>Usuarios y roles</h3><p>Crea accesos individuales. El límite depende del plan contratado.</p><form className="user-create-form" autoComplete="off" onSubmit={createUser}><input autoComplete="off" placeholder="Nombre completo" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><input autoComplete="off" type="email" placeholder="Correo" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/><select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option>Administrador</option><option>Asesor</option><option>Técnico</option><option>Contador</option><option>Consulta</option></select><input autoComplete="new-password" type="password" minLength={10} placeholder="Contraseña temporal (mín. 10)" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/><button className="primary-button" disabled={busy||!form.name||!form.email||form.password.length<10}>{busy?<LoaderCircle className="spin"/>:<UserPlus/>}Crear usuario</button></form><div className="users-list">{usersList.map(user=><div key={user.id}><span className="avatar">{initials(user.name)}</span><div><b>{user.name}</b><small>{user.email}</small></div><span className="status-pill">{user.role}</span></div>)}</div></>}{tab==='integrations'&&<><h3>Integraciones</h3><p>Conectores externos y su estado actual.</p><div className="integration-row"><span className="integration-icon whatsapp"><MessageCircle/></span><div><b>WhatsApp</b><small>Enlace real con mensajes prellenados; automatización requiere Meta Business.</small></div><span className="connected"><i/>Manual activo</span><button className="secondary-button" onClick={()=>notify('WhatsApp manual está disponible desde cada orden')}>Probar</button></div><div className="integration-row"><span className="integration-icon cloud"><Camera/></span><div><b>Evidencias</b><small>Local en demo; Supabase Storage privado en producción.</small></div><span className="connected"><i/>Demo activa</span><button className="secondary-button" onClick={()=>notify('Almacenamiento local funcionando')}>Estado</button></div><div className="integration-row"><span className="integration-icon invoice"><FileCheck2/></span><div><b>Facturación electrónica DIAN</b><small>Requiere proveedor tecnológico y habilitación comercial.</small></div><span className="pending-dot">Pendiente</span><button className="secondary-button" onClick={()=>notify('Se necesitan credenciales de un proveedor tecnológico','error')}>Requisitos</button></div></>}{tab==='security'&&<><h3>Seguridad de la plataforma</h3><p>Controles ya preparados y requisitos antes de producción.</p><div className="security-list"><div><CheckCircle2/><span><b>Backend reforzado</b><small>Cabeceras seguras, límite de intentos, JWT con vencimiento y contraseñas bcrypt.</small></span></div><div><CheckCircle2/><span><b>Aislamiento por taller</b><small>Esquema PostgreSQL con workshop_id y políticas RLS.</small></span></div><div><ShieldCheck/><span><b>Pendiente de tus cuentas</b><small>Dominio HTTPS, Supabase Auth con MFA, backups y llaves reales de Wompi.</small></span></div></div></>}</div></div></div>
}

function CustomerModal({close,create,notify}:{close:()=>void;create:(d:any)=>Promise<void>;notify:(m:string,t?:'ok'|'error')=>void}){const[step,setStep]=useState(1),[busy,setBusy]=useState(false),[form,setForm]=useState({type:'Persona natural',documentType:'CC',document:'',name:'',phone:'',email:'',address:'',plate:'',brand:'',model:'',year:new Date().getFullYear(),color:'',mileage:0});const field=(k:string,v:any)=>setForm({...form,[k]:v});const submit=async()=>{setBusy(true);try{await create({...form,vehicles:form.plate?[{id:`veh_${Date.now()}`,plate:form.plate.toUpperCase(),brand:form.brand,model:form.model,year:Number(form.year),color:form.color,mileage:Number(form.mileage)}]:[]});notify('Cliente y vehículo guardados');close()}catch(err){notify(err instanceof Error?err.message:'Error','error')}finally{setBusy(false)}};return <div className="modal-overlay"><div className="modal"><div className="modal-head"><div><span className="modal-icon"><UserPlus/></span><div><h3>Nuevo cliente</h3><p>Se guardará en el backend</p></div></div><button className="icon-button" onClick={close}><X/></button></div><div className="modal-steps"><span className="active">1</span><i/><span className={step===2?'active':''}>2</span><p>{step===1?'Información personal':'Vehículo principal'}</p></div>{step===1?<div className="form-grid"><label>Tipo de cliente<select value={form.type} onChange={e=>field('type',e.target.value)}><option>Persona natural</option><option>Empresa</option></select></label><label>Tipo de documento<select value={form.documentType} onChange={e=>field('documentType',e.target.value)}><option>CC</option><option>NIT</option><option>CE</option></select></label><label>Número de documento<input value={form.document} onChange={e=>field('document',e.target.value)} required/></label><label>Nombre completo / razón social<input value={form.name} onChange={e=>field('name',e.target.value)} required/></label><label>Teléfono / WhatsApp<input value={form.phone} onChange={e=>field('phone',e.target.value)} required/></label><label>Correo<input value={form.email} onChange={e=>field('email',e.target.value)}/></label><label className="full-field">Dirección<input value={form.address} onChange={e=>field('address',e.target.value)}/></label></div>:<div className="form-grid"><label>Placa<input value={form.plate} onChange={e=>field('plate',e.target.value.toUpperCase())}/></label><label>Marca<input value={form.brand} onChange={e=>field('brand',e.target.value)}/></label><label>Modelo / línea<input value={form.model} onChange={e=>field('model',e.target.value)}/></label><label>Año<input type="number" value={form.year} onChange={e=>field('year',e.target.value)}/></label><label>Color<input value={form.color} onChange={e=>field('color',e.target.value)}/></label><label>Kilometraje<input type="number" value={form.mileage} onChange={e=>field('mileage',e.target.value)}/></label></div>}<div className="modal-footer"><button className="secondary-button" onClick={step===1?close:()=>setStep(1)}>{step===1?'Cancelar':'Atrás'}</button><button className="primary-button" disabled={busy||(!form.name||!form.document||!form.phone)} onClick={step===1?()=>setStep(2):submit}>{busy?<LoaderCircle className="spin"/>:step===1?'Continuar':'Crear cliente'}<ChevronRight/></button></div></div></div>}

function OrderModal({customers,close,create,notify}:{customers:Customer[];close:()=>void;create:(d:any)=>Promise<void>;notify:(m:string,t?:'ok'|'error')=>void}){
  const[customerId,setCustomerId]=useState(customers[0]?.id||''),[vehicleId,setVehicleId]=useState(customers[0]?.vehicles[0]?.id||''),[area,setArea]=useState(serviceAreas[0]),[tech,setTech]=useState('Por asignar'),[reason,setReason]=useState(''),[arrivalContact,setArrivalContact]=useState(''),[paintColor,setPaintColor]=useState(''),[affected,setAffected]=useState(''),[busy,setBusy]=useState(false)
  const customer=customers.find(c=>c.id===customerId)
  useEffect(()=>{setVehicleId(customer?.vehicles[0]?.id||'')},[customerId])
  const submit=async()=>{setBusy(true);try{await create({customerId,vehicleId,serviceArea:area,tech,reason,arrivalContact,paintColor,affectedAreas:affected.split(',').map(x=>x.trim()).filter(Boolean),fuel:'Por registrar',receivedItems:'Llave + documentos'});notify('Orden creada y persistida');close()}catch(err){notify(err instanceof Error?err.message:'Error','error')}finally{setBusy(false)}}
  return <div className="modal-overlay"><div className="modal"><div className="modal-head"><div><span className="modal-icon"><ClipboardList/></span><div><h3>Nueva orden multiservicio</h3><p>Mecánica, pintura y servicios automotrices</p></div></div><button className="icon-button" onClick={close}><X/></button></div><div className="form-grid"><label>Cliente<select value={customerId} onChange={e=>setCustomerId(e.target.value)}>{customers.map(c=><option value={c.id} key={c.id}>{c.name} · {c.document}</option>)}</select></label><label>Vehículo<select value={vehicleId} onChange={e=>setVehicleId(e.target.value)}>{customer?.vehicles.map(v=><option value={v.id} key={v.id}>{v.brand} {v.model} · {v.plate}</option>)}</select></label><label className="full-field">Persona que entrega el vehículo <span className="optional-label">Opcional</span><input value={arrivalContact} onChange={e=>setArrivalContact(e.target.value)} maxLength={180} placeholder="Nombre, parentesco o identificación si deseas registrarla"/></label><label>Área de servicio<select value={area} onChange={e=>setArea(e.target.value)}>{serviceAreas.map(a=><option key={a}>{a}</option>)}</select></label><label>Técnico responsable<select value={tech} onChange={e=>setTech(e.target.value)}><option>Por asignar</option><option>Andrés López</option><option>Diego Pérez</option><option>Camilo Ruiz</option><option>Especialista externo</option></select></label>{area==='Latonería y pintura'&&<><label>Color / código de pintura<input value={paintColor} onChange={e=>setPaintColor(e.target.value)} placeholder="Ej. Blanco / NH-883P"/></label><label>Zonas afectadas<input value={affected} onChange={e=>setAffected(e.target.value)} placeholder="Puerta, capó, guardabarros"/></label></>}<label className="full-field">Motivo de ingreso / trabajo solicitado<textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="Describe el diagnóstico solicitado o daño visible..."/></label></div><div className="modal-footer"><button className="secondary-button" onClick={close}>Cancelar</button><button className="primary-button" onClick={submit} disabled={busy||!customerId||!vehicleId||!reason}>{busy?<LoaderCircle className="spin"/>:<Check/>}Crear orden</button></div></div></div>
}

function ExpenseModal({close,create,notify}:{close:()=>void;create:(d:any)=>Promise<void>;notify:(m:string,t?:'ok'|'error')=>void}){const[description,setDescription]=useState(''),[category,setCategory]=useState('Servicios externos'),[amount,setAmount]=useState(0),[busy,setBusy]=useState(false);const submit=async()=>{setBusy(true);try{await create({description,category,amount});notify('Gasto registrado');close()}catch(err){notify(err instanceof Error?err.message:'Error','error')}finally{setBusy(false)}};return <div className="modal-overlay"><div className="modal compact-modal"><div className="modal-head"><div><span className="modal-icon"><WalletCards/></span><div><h3>Registrar gasto</h3><p>Movimiento contable básico</p></div></div><button className="icon-button" onClick={close}><X/></button></div><div className="form-grid"><label>Categoría<select value={category} onChange={e=>setCategory(e.target.value)}><option>Servicios externos</option><option>Materiales de pintura</option><option>Repuestos por orden</option><option>Servicios públicos</option><option>Otros</option></select></label><label>Valor<input type="number" min="1" value={amount} onChange={e=>setAmount(Number(e.target.value))}/></label><label className="full-field">Descripción<input value={description} onChange={e=>setDescription(e.target.value)}/></label></div><div className="modal-footer"><button className="secondary-button" onClick={close}>Cancelar</button><button className="primary-button" onClick={submit} disabled={busy||!description||amount<=0}>Guardar</button></div></div></div>}

function InvoiceModal({orders,close,create,notify}:{orders:Order[];close:()=>void;create:(d:any)=>Promise<void>;notify:(m:string,t?:'ok'|'error')=>void}){const[orderId,setOrderId]=useState(orders[0]?.id||''),[next,setNext]=useState(''),[busy,setBusy]=useState(false);const order=orders.find(o=>o.id===orderId);const submit=async()=>{if(!order)return;setBusy(true);try{await create({orderId:order.id,customer:order.customer,total:order.value,nextMaintenance:next});notify('Factura de demostración creada');close()}catch(err){notify(err instanceof Error?err.message:'Error','error')}finally{setBusy(false)}};return <div className="modal-overlay"><div className="modal compact-modal"><div className="modal-head"><div><span className="modal-icon"><ReceiptText/></span><div><h3>Nueva factura</h3><p>Documento de venta de demostración</p></div></div><button className="icon-button" onClick={close}><X/></button></div><div className="form-grid"><label className="full-field">Orden<select value={orderId} onChange={e=>setOrderId(e.target.value)}>{orders.map(o=><option key={o.id} value={o.id}>{o.id} · {o.customer} · {money(o.value)}</option>)}</select></label><label>Próximo mantenimiento<input type="date" value={next} onChange={e=>setNext(e.target.value)}/></label><label>Total<input value={money(order?.value||0)} disabled/></label></div><div className="modal-footer"><button className="secondary-button" onClick={close}>Cancelar</button><button className="primary-button" onClick={submit} disabled={busy||!order}>Generar factura</button></div></div></div>}

export default function App(){
  const recoveryAccess=new URLSearchParams(window.location.hash.replace(/^#/,'')).has('access_token')
  const[logged,setLogged]=useState(Boolean(session.token())&&!recoveryAccess),[data,setData]=useState<Bootstrap|null>(null),[page,setPage]=useState<Page>('dashboard'),[selectedId,setSelectedId]=useState<string|null>(null),[menu,setMenu]=useState(false),[modal,setModal]=useState<'order'|'customer'|'expense'|'invoice'|null>(null),[search,setSearch]=useState(''),[loading,setLoading]=useState(false),[toast,setToast]=useState<{message:string;type:'ok'|'error'}|null>(null)
  const notify=(message:string,type:'ok'|'error'='ok')=>{setToast({message,type});setTimeout(()=>setToast(null),3200)}
  const load=async()=>{if(!session.token())return;setLoading(true);try{const value=await api.bootstrap();setData(value);setLogged(true)}catch(err){session.clear();setLogged(false);notify(err instanceof Error?err.message:'Sesión no válida','error')}finally{setLoading(false)}}
  useEffect(()=>{if(logged){void load()}},[logged])
  useEffect(()=>{if(!logged)return;const cleanup=subscribe(()=>{void load()});return cleanup},[logged])
  useEffect(()=>{window.scrollTo({top:0,behavior:'smooth'})},[page,selectedId])
  const selected=data?.orders.find(o=>o.id===selectedId)||null
  const filteredOrders=useMemo(()=>{if(!data)return[];const q=search.toLowerCase().trim();return q?data.orders.filter(o=>`${o.id} ${o.customer} ${o.plate} ${o.car} ${o.serviceArea}`.toLowerCase().includes(q)):data.orders},[data,search])
  const onLogin=async(email:string,password:string)=>{await apiLogin(email,password);setLogged(true)}
  const updateOrder=async(order:Order)=>{const updated=await api.updateOrder(order.id,order);setData(d=>d?{...d,orders:d.orders.map(o=>o.id===updated.id?updated:o)}:d)}
  const createCustomer=async(value:any)=>{const created=await api.createCustomer(value);setData(d=>d?{...d,customers:[created,...d.customers]}:d)}
  const createOrder=async(value:any)=>{const created=await api.createOrder(value);setData(d=>d?{...d,orders:[created,...d.orders]}:d);setSelectedId(created.id)}
  const createExpense=async(value:any)=>{const created=await api.addExpense(value);setData(d=>d?{...d,expenses:[created,...d.expenses]}:d)}
  const createInvoice=async(value:any)=>{const created=await api.addInvoice(value);setData(d=>d?{...d,invoices:[created,...d.invoices]}:d)}
  const reset=async()=>{if(!window.confirm('¿Reiniciar todos los datos de la demostración?'))return;const fresh=await api.reset();setData(fresh);setSelectedId(null);setPage('dashboard');notify('Demo reiniciada')}
  if(!logged)return <Login onLogin={onLogin} onAuthenticated={()=>setLogged(true)}/>
  if(!data||loading)return <div className="app-loader"><Logo/><LoaderCircle className="spin"/><p>Conectando con el backend...</p></div>
  const title=selected?selected.id:navigation.find(n=>n.page===page)?.label||'Configuración'
  return <div className="app-shell"><Sidebar page={page} setPage={p=>{setPage(p);setSelectedId(null)}} open={menu} close={()=>setMenu(false)} logout={()=>{session.clear();setLogged(false)}} workshop={data.workshop} orderCount={data.orders.filter(o=>o.stage!=='Entrega').length}/><main className="app-main"><Header title={title} subtitle={selected?'Detalle y trazabilidad persistente':undefined} openMenu={()=>setMenu(true)} onNew={()=>setModal('order')} search={search} setSearch={setSearch}/>{selected?<OrderDetail order={selected} update={updateOrder} refresh={load} back={()=>setSelectedId(null)} notify={notify}/>:page==='dashboard'?<Dashboard data={data} onOrder={o=>setSelectedId(o.id)} onNew={()=>setModal('order')} onCustomer={()=>setModal('customer')} setPage={setPage}/>:page==='orders'?<OrdersPage orders={filteredOrders} onOpen={o=>setSelectedId(o.id)} onNew={()=>setModal('order')}/>:page==='customers'?<CustomersPage customers={data.customers} orders={data.orders} onAdd={()=>setModal('customer')} onOpenOrder={o=>setSelectedId(o.id)}/>:page==='quotes'?<QuotesPage orders={data.orders} onOpen={o=>setSelectedId(o.id)}/>:page==='sales'?<SalesPage invoices={data.invoices} orders={data.orders} onNew={()=>setModal('invoice')}/>:page==='accounting'?<AccountingPage expenses={data.expenses} invoices={data.invoices} onExpense={()=>setModal('expense')}/>:page==='reports'?<ReportsPage data={data}/>:page==='billing'?<BillingPage notify={notify}/>:<SettingsPage workshop={data.workshop} onReset={reset} notify={notify}/>}</main>{modal==='customer'&&<CustomerModal close={()=>setModal(null)} create={createCustomer} notify={notify}/>} {modal==='order'&&<OrderModal customers={data.customers} close={()=>setModal(null)} create={createOrder} notify={notify}/>} {modal==='expense'&&<ExpenseModal close={()=>setModal(null)} create={createExpense} notify={notify}/>} {modal==='invoice'&&<InvoiceModal orders={data.orders} close={()=>setModal(null)} create={createInvoice} notify={notify}/>} {toast&&<div className={`toast ${toast.type}`}><span>{toast.type==='ok'?<CheckCircle2/>:<Activity/>}</span>{toast.message}</div>}</div>
}
